insert into public.eleao_articles(id,category,question,answer,source,keywords) values
('guia-1','Reforma tributária','Qual é a diferença entre IBS e CBS?','A CBS é a contribuição federal sobre bens e serviços. O IBS é o imposto de competência compartilhada entre estados, municípios e Distrito Federal. No e-Leão, os dois valores aparecem separados: uma simulação não representa, por si só, um saldo a recolher.','https://github.com/ReceitaFederal/calculadora-rtc-regime-regular/tree/150cccbe414d4a5edea703e4f7a424af5aa222c7','diferença tributos reforma significado cbs ibs imposto consumo'),
('guia-2','Calculadora','Como fazer minha primeira simulação?','Abra a Calculadora RTC, selecione o regime e informe a base tributável já ajustada. Confira as alíquotas do seu cenário antes de calcular. Revise a memória e use Salvar simulação para incluí-la no histórico. Na demonstração, ela fica apenas nesta aba.','https://github.com/ReceitaFederal/calculadora-rtc-regime-regular/tree/150cccbe414d4a5edea703e4f7a424af5aa222c7','simular calcular calculadora primeira salvar cálculo'),
('guia-3','Notas de serviço','Como emitir uma NFS-e?','Em Notas de serviço, prepare e salve um rascunho. Confira o tomador, a competência, o serviço e o valor. Use Abrir emissor nacional e conclua a emissão no ambiente autorizado, se o seu município e regime forem atendidos; caso contrário, utilize o emissor municipal. Só a autorização no emissor gera a nota.','https://www.nfse.gov.br/EmissorNacional','nota emitir emissão nfse nfs-e prefeitura certificado rascunho serviço'),
('guia-4','Simples Nacional','O cálculo do Simples Nacional substitui o DAS?','Não. O motor RTC do Simples trata IBS e CBS por operação, com CRT, atividade, classificação e alíquotas efetivas. Não faz a apuração mensal do PGDAS-D. A estimativa rápida usa os percentuais efetivos que você informa; não escolhe anexo nem calcula fator R.','https://github.com/ReceitaFederal/calculadora-rtc-simples-nacional/tree/c5b0f01c8351c3f0d0795cc617b29d233e9f98df','simples nacional das pgdas anexo fator r'),
('guia-5','Notas de serviço','O que é o DANFSe?','É a representação auxiliar, em PDF, da NFS-e. O gerador da Receita recebe o XML de uma nota e monta o documento para leitura. Ele não assina uma DPS, não transmite a nota e não verifica sua autenticidade no portal. Use o XML autorizado fornecido pelo emissor.','https://github.com/ReceitaFederal/calculadora-rtc-gerador-danfse/tree/8d79e6b2f7fad6375340afcb51c85ed370c64a14','danfse pdf xml impressão documento auxiliar'),
('guia-6','Calculadora','Quando usar o Imposto Seletivo?','O IS tem hipóteses específicas de incidência. Não se aplica automaticamente a toda prestação de serviço. Na estimativa, inclua-o somente se tiver identificado a incidência, a base própria e a alíquota ad valorem. Para classificações e modalidades específicas, consulte o motor RTC e a legislação.','https://github.com/ReceitaFederal/calculadora-rtc-regime-regular/tree/150cccbe414d4a5edea703e4f7a424af5aa222c7','is seletivo incidência base ad valorem'),
('guia-7','Reforma tributária','Posso usar qualquer alíquota a partir de 2027?','Não como alíquota oficial. Na versão analisada do motor regular, operações a partir de 2027 exigem alíquotas nominais informadas e o resultado é identificado como simulado. Antes de 2027 esse bloco não deve ser enviado. Verifique vigências, enquadramento e avisos antes de usar os números.','https://github.com/ReceitaFederal/calculadora-rtc-regime-regular/tree/150cccbe414d4a5edea703e4f7a424af5aa222c7','2026 2027 vigência alíquotas percentuais transição'),
('guia-8','Calculadora','Por que um item não foi calculado?','No modo de observabilidade, uma resposta HTTP 200 pode conter itens inconsistentes, não implementados ou não calculados. Leia o estado e os erros de cada item. Totais parciais não representam o total da operação. Confira a classificação, o documento e a data antes de recalcular.','https://github.com/ReceitaFederal/calculadora-rtc-simples-nacional/tree/c5b0f01c8351c3f0d0795cc617b29d233e9f98df','erro estado observabilidade resultado parcial calculado cst classificação');
